const defaultWorkspace:Workspace={openProjects:[],activeProject:null,compareProject:null,layouts:{},hiddenModules:{},density:'comfortable',longPressMs:1000,views:[]};
const validUrl=(url:string)=>Boolean(safeUrl(url));
const validPreviews=(value:unknown):Preview[]=>Array.isArray(value)?(value as Preview[]).filter(p=>p&&typeof p.id==='string'&&typeof p.url==='string'&&typeof p.title==='string'&&safeUrl(p.url)):[];
